solution:
#include <iostream>
#include <iomanip>

int main() {
    int a, b, c;
    std::cin >> a >> b >> c;
    double moyenne = static_cast<double>(a + b + c) / 3;
    std::cout << "Moyenne : " << std::fixed << std::setprecision(2) << moyenne << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>
#include <string>

int main() {
    std::string client;
    std::getline(std::cin, client);
    int prix, tas;
    std::cin >> prix >> tas;
    int total = prix * tas;
    std::cout << "Client : " << client << "\n";
    std::cout << "Total : " << total << " FCFA\n";
    std::cout << "Prix moyen par tas : " << std::fixed << std::setprecision(1) << static_cast<double>(total) / tas << " FCFA\n";
    return 0;
}
